-.empty { background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius); padding: 36px 20px; text-align: center; color: var(--ink-soft); }
+.empty { background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius); padding: 36px 20px; text-align: center; color: var(--ink-soft); }
+
+.grid-wrap { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px; overflow-x: auto; }
+.tz-table, .tz-table-vertical { border-collapse: separate; border-spacing: 2px; width: 100%; }
+.tz-table { min-width: 1120px; table-layout: fixed; }
+.tz-table .city-col { width: 190px; }
+.tz-table th, .tz-table td, .tz-table-vertical th, .tz-table-vertical td { text-align: center; }
+.hour-head { font-size: 11px; color: var(--ink-soft); font-weight: 700; padding: 6px 0 8px; font-variant-numeric: tabular-nums; white-space: nowrap; }
+.hour-head.now { color: var(--green-dark); }
+.now-dot { display: block; font-size: 7px; line-height: 1; color: var(--green); }
+.city-cell, .mobile-city-head { text-align: left !important; vertical-align: middle; padding: 8px 10px; }
+.city-cell { background: #f5f8f9; border-radius: 7px; }
+.ref-row .city-cell, .mobile-city-head.ref-col { background: #e9f6ee; }
+.city-name { border: 0; background: transparent; padding: 0; font-weight: 800; font-size: 15px; color: var(--ink); cursor: pointer; text-align: left; }
+.city-name:hover { color: var(--green-dark); text-decoration: underline; }
+.ref-badge {
+  display: inline-block; margin-left: 7px; vertical-align: 2px;
+  background: var(--green); color: #fff; font-size: 10px; font-weight: 800; letter-spacing: 0.6px;
+  padding: 2px 6px; border-radius: 4px;
+}
+.city-sub { display: block; color: var(--ink-soft); font-size: 12.5px; font-weight: 500; }
+.city-meta { display: block; color: var(--ink-faint); font-size: 12px; font-variant-numeric: tabular-nums; font-weight: 500; }
+.cell {
+  padding: 10px 0; border-radius: 5px; font-size: 12px; white-space: nowrap;
+  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-variant-numeric: tabular-nums;
+}
+.cell.sleeping { background: #edf0f2; color: #9aa7b1; }
+.cell.awake { background: #fff; color: var(--ink); box-shadow: inset 0 0 0 1px var(--line); }
+.cell.overlap { background: var(--green); color: #fff; font-weight: 800; box-shadow: inset 0 0 0 1px var(--green-dark); }
+.cell.now-col { outline: 2px solid #d99a16; outline-offset: -2px; }
+.remove-cell { width: 34px; }
+.remove-btn {
+  border: 1px solid var(--line); background: #fff; color: var(--ink-faint); border-radius: 50%;
+  width: 26px; height: 26px; line-height: 1; font-size: 16px; cursor: pointer; padding: 0;
+}
+.remove-btn:hover { color: #b3261e; border-color: #b3261e; }
+
+.tz-table-vertical { table-layout: fixed; min-width: 0; }
+.tz-table-vertical .hour-col { width: 62px; }
+.mobile-city-head { background: #f5f8f9; border-radius: 7px; vertical-align: top; position: relative; }
+.mobile-city-head .city-name { font-size: 13.5px; }
+.mobile-city-head .remove-btn { margin-top: 6px; }
+.mobile-hour { font-size: 12px; color: var(--ink-soft); font-variant-numeric: tabular-nums; white-space: nowrap; padding: 4px 2px; }
+.now-row .mobile-hour { color: var(--green-dark); }
+.tz-table-vertical .cell { padding: 8px 0; font-size: 11.5px; }
+
+.legend {
+  display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px;
+  color: var(--ink-soft); font-size: 13.5px; padding: 2px 4px 8px;
+}
+.legend-item { display: inline-flex; align-items: center; gap: 7px; }
+.swatch { width: 16px; height: 16px; border-radius: 4px; display: inline-block; }
+.swatch.overlap { background: var(--green); }
+.swatch.awake { background: #fff; box-shadow: inset 0 0 0 1px var(--line); }
+.swatch.sleeping { background: #edf0f2; box-shadow: inset 0 0 0 1px var(--line); }
+.hint { font-weight: 800; color: var(--ink); }
+.footnote { color: var(--ink-faint); font-size: 12.5px; }
+@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }
+@media (max-width: 767px) {
+  .main { padding: 12px; }
+  .topbar-inner { padding: 18px 14px 4px; }
+  .mode-hint { padding: 6px 14px 14px; }
+  .grid-wrap { padding: 6px; }
+  .summary-city { min-width: 0; }
+}

